package main

import (
	"fmt"
	"log"
	"net/http"
	"os"

	"github.com/gin-gonic/gin"
	ldap "github.com/go-ldap/ldap/v3"
)

var ldapConn *ldap.Conn

func init() {
	var err error
	ldapHost := os.Getenv("LDAP_HOST")
	if ldapHost == "" {
		ldapHost = "ldap://directory.internal:389"
	}
	ldapConn, err = ldap.DialURL(ldapHost)
	if err != nil {
		log.Fatalf("Failed to connect to LDAP: %v", err)
	}
	err = ldapConn.Bind(os.Getenv("LDAP_BIND_DN"), os.Getenv("LDAP_BIND_PW"))
	if err != nil {
		log.Fatalf("Failed to bind LDAP: %v", err)
	}
}

type UserLookupRequest struct {
	Username string `json:"username" binding:"required"`
	Department string `json:"department"`
}

// lookupUser searches the corporate directory for user attributes
// Used by the provisioning service to sync user metadata to DynamoDB
func lookupUser(c *gin.Context) {
	var req UserLookupRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid request"})
		return
	}

	// Build LDAP filter - department is optional narrowing filter
	var filter string
	if req.Department != "" {
		filter = fmt.Sprintf("(&(objectClass=person)(uid=%s)(department=%s))", req.Username, req.Department)
	} else {
		filter = fmt.Sprintf("(&(objectClass=person)(uid=%s))", req.Username)
	}

	baseDN := os.Getenv("LDAP_BASE_DN")
	if baseDN == "" {
		baseDN = "dc=corp,dc=internal"
	}

	searchReq := ldap.NewSearchRequest(
		baseDN,
		ldap.ScopeWholeSubtree,
		ldap.NeverDerefAliases,
		100, // size limit
		10,  // time limit
		false,
		filter,
		[]string{"uid", "cn", "mail", "department", "employeeNumber", "memberOf"},
		nil,
	)

	result, err := ldapConn.Search(searchReq)
	if err != nil {
		log.Printf("LDAP search error: %v", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "directory lookup failed"})
		return
	}

	if len(result.Entries) == 0 {
		c.JSON(http.StatusNotFound, gin.H{"error": "user not found"})
		return
	}

	users := make([]gin.H, 0, len(result.Entries))
	for _, entry := range result.Entries {
		users = append(users, gin.H{
			"uid":        entry.GetAttributeValue("uid"),
			"name":       entry.GetAttributeValue("cn"),
			"email":      entry.GetAttributeValue("mail"),
			"department": entry.GetAttributeValue("department"),
			"employeeId": entry.GetAttributeValue("employeeNumber"),
			"groups":     entry.GetAttributeValues("memberOf"),
		})
	}

	c.JSON(http.StatusOK, gin.H{"results": users})
}

// healthCheck verifies LDAP connectivity
func healthCheck(c *gin.Context) {
	if ldapConn == nil {
		c.JSON(http.StatusServiceUnavailable, gin.H{"status": "unhealthy"})
		return
	}
	c.JSON(http.StatusOK, gin.H{"status": "healthy"})
}

func main() {
	r := gin.Default()
	r.POST("/api/v1/directory/lookup", lookupUser)
	r.GET("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting directory sync service on :%s", port)
	r.Run(":" + port)
}
